async function signer() { const ethereum = (window as Window & { ethereum?: Eip1193Provider }).ethereum; if (!ethereum) throw new Error("MetaMask is required."); const provider = new BrowserProvider(ethereum); try { await provider.send("wallet_switchEthereumChain", [{ chainId: "0xaa36a7" }]); } catch (error) { const code = (error as { code?: number }).code; if (code !== 4902) throw error; await provider.send("wallet_addEthereumChain", [{ chainId: "0xaa36a7", chainName: "Sepolia Testnet", nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 }, rpcUrls: ["https://ethereum-sepolia-rpc.publicnode.com"], blockExplorerUrls: ["https://sepolia.etherscan.io"] }]); await provider.send("wallet_switchEthereumChain", [{ chainId: "0xaa36a7" }]); } const account = await provider.getSigner(); live.wallet = await account.getAddress(); const button = document.getElementById("walletBtn"); if (button) button.textContent = `${live.wallet.slice(0, 7)}...${live.wallet.slice(-4)}`; const balance = document.getElementById("balanceChip"); if (balance) balance.textContent = "Balance: live Sepolia ETH"; return { provider, account }; }
async function connectWallet() { try { const session = await signer(); await loadLivePortfolio(session.account); message("MetaMask connected to Sepolia."); } catch (error) { message(error instanceof Error ? error.message : "Wallet connection failed."); } }
async function apiToken(account: Awaited<ReturnType<typeof signer>>["account"]) {
  if (!apiBase) throw new Error("Daily API URL is not configured for this build.");
  const address = await account.getAddress();
  const challengeResponse = await fetch(`${apiBase}/v1/auth/challenge`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ address }) });
  if (!challengeResponse.ok) throw new Error("Daily API could not create a wallet-signature challenge.");
  const { message: challenge } = await challengeResponse.json() as { message: string };
  const verification = await fetch(`${apiBase}/v1/auth/verify`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ address, signature: await account.signMessage(challenge) }) });
  if (!verification.ok) throw new Error("Daily API rejected the wallet signature.");
  return (await verification.json() as { token: string }).token;
}
function renderSelection() { const total = live.results.filter(result => live.selected.has(result.tld)).reduce((sum, result) => sum + Number(result.priceWei ?? 0n), 0); const target = document.getElementById("selectedTotal"); if (target) target.textContent = `${total / 1e18} ETH`; const continueButton = document.getElementById("continueRegistration") as HTMLButtonElement | null; if (continueButton) continueButton.disabled = live.selected.size === 0; }
type PortfolioName = { name: string; expiry?: number; owner: string; resolver?: string };
async function loadLivePortfolio(account: Awaited<ReturnType<typeof signer>>["account"]) {
  const target = document.getElementById("ownedNamesList"); if (!target || !apiBase) return;
  try {
    const response = await fetch(`${apiBase}/v1/portfolio`, { headers: { authorization: `Bearer ${await apiToken(account)}` } }); if (!response.ok) throw new Error("Unable to load the indexed portfolio.");
    const { names } = await response.json() as { names: PortfolioName[] };
    const now = Math.floor(Date.now() / 1000); const expiring = names.filter(name => name.expiry && name.expiry - now <= 30 * 86_400).length;
    target.innerHTML = names.length ? `<div class="panel section"><div class="head"><div><h3>My Daily names</h3><p>Indexed registrations verified against current on-chain ownership.</p></div><span class="badge ${expiring ? "gold" : "green"}">${expiring ? `${expiring} expiring within 30 days` : `${names.length} live`}</span></div><table class="table"><tr><th>Name</th><th>Expiry</th><th>Reminder</th><th></th></tr>${names.map(name => { const days = name.expiry ? Math.ceil((name.expiry - now) / 86_400) : undefined; const reminder = days === undefined ? "--" : days < 0 ? "Expired — renewal grace may apply" : days <= 30 ? `${days} day${days === 1 ? "" : "s"} remaining` : "Active"; return `<tr><td><b>${name.name}</b></td><td>${name.expiry ? new Date(name.expiry * 1000).toLocaleDateString() : "--"}</td><td>${reminder}</td><td><button class="btn ghost" onclick="dailyLiveOpenName('${name.name}')">Manage</button></td></tr>`; }).join("")}</table></div>` : `<div class="panel section"><h3>No Daily names found</h3><p>Your connected wallet has no names in the synchronized Sepolia index.</p></div>`;
    const activityResponse = await fetch(`${apiBase}/v1/activity`, { headers: { authorization: `Bearer ${await apiToken(account)}` } }); const activity = activityResponse.ok ? (await activityResponse.json() as { activity: Array<{ event_name: string; transaction_hash: string; block_number: number; created_at: string }> }).activity : [];
    const activityHost = document.createElement("div"); activityHost.className = "panel section"; activityHost.innerHTML = `<div class="head"><div><h3>On-chain activity</h3><p>Indexed protocol events associated with this connected wallet.</p></div><span class="badge purple">${activity.length} events</span></div><table class="table"><tr><th>Event</th><th>Block</th><th>Transaction</th><th>Recorded</th></tr>${activity.map(event => `<tr><td>${event.event_name}</td><td>${event.block_number}</td><td>${event.transaction_hash}</td><td>${new Date(event.created_at).toLocaleString()}</td></tr>`).join("") || "<tr><td colspan=\"4\">No indexed activity is available yet.</td></tr>"}</table>`; target.append(activityHost);
    await loadLivePremiumRequests(account);
  } catch (error) { target.innerHTML = `<div class="panel section"><h3>Portfolio unavailable</h3><p>${error instanceof Error ? error.message : "Unable to load the live portfolio."}</p></div>`; }
}
