async function loadLivePremiumRequests(account: Awaited<ReturnType<typeof signer>>["account"]) {
  const target = document.getElementById("premiumRequestList"); if (!target || !apiBase) return;
  try {
    const response = await fetch(`${apiBase}/v1/premium-requests`, { headers: { authorization: `Bearer ${await apiToken(account)}` } });
    if (!response.ok) throw new Error("Unable to load premium requests.");
    const { requests } = await response.json() as { requests: PremiumRequest[] };
    target.innerHTML = requests.length ? requests.map(request => `<div class="panel" style="margin-top:12px"><span class="badge ${request.status === "quoted" ? "green" : request.status === "rejected" ? "red" : "gold"}">${request.status === "submitted" ? "Pending admin review" : request.status}</span><h3 style="margin-top:12px">${request.name}</h3><p>${request.duration_years} year${request.duration_years === 1 ? "" : "s"} · ${request.reason}</p>${request.status === "quoted" ? `<div class="grid3"><div class="metric"><b>${formatEther(BigInt(request.quoted_registration_wei ?? "0"))} ETH</b><span>registration</span></div><div class="metric"><b>${formatEther(BigInt(request.quoted_renewal_wei ?? "0"))} ETH</b><span>annual renewal</span></div><div class="metric"><b>${request.quote_expires_at ? new Date(request.quote_expires_at).toLocaleString() : "--"}</b><span>quote expiry</span></div></div><button class="btn gold" onclick="dailyLiveAcceptPremium('${request.name}',${request.duration_years})">Accept quote and register</button>` : request.status === "rejected" ? `<p class="muted">This request was rejected by the protected admin workflow.</p>` : `<p class="muted">No payment has been requested.</p>`}</div>`).join("") : `<p class="muted">No premium requests submitted by this wallet.</p>`;
  } catch (error) { target.innerHTML = `<p class="muted">${error instanceof Error ? error.message : "Unable to load premium requests."}</p>`; }
}
function premiumValue(id: string) { return (document.getElementById(id) as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement | null)?.value.trim() ?? ""; }
async function submitLivePremium() {
  try {
    if (!apiBase) throw new Error("Daily API URL is not configured for this build.");
    const name = premiumValue("premiumName"); const durationText = premiumValue("premiumDuration"); const durationYears = Number((durationText.match(/^\d+/)?.[0] ?? "0"));
    const reason = premiumValue("v35PremiumType") || premiumValue("premiumReason") || "Personal premium request";
    const note = premiumValue("v35PremiumMessage") || premiumValue("premiumNote");
    const files = (document.getElementById("v35PremiumFiles") as HTMLInputElement | null)?.files;
    if (!name || !Number.isInteger(durationYears) || durationYears < 1 || durationYears > 10 || note.length < 1) throw new Error("Complete the premium name, registration period, and message.");
    if (files?.length) throw new Error("Encrypted brand-evidence upload needs the production evidence-recipient key. The request was not submitted and no file was uploaded.");
    const { account } = await signer();
    const response = await fetch(`${apiBase}/v1/premium-requests`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${await apiToken(account)}` }, body: JSON.stringify({ name, durationYears, reason: `${reason} request`.padEnd(10, " "), note }) });
    if (!response.ok) throw new Error((await response.json().catch(() => ({ error: "Premium request failed." })) as { error?: string }).error ?? "Premium request failed.");
    const status = document.getElementById("premiumStatusPanel"); if (status) status.innerHTML = `<span class="badge gold">Pending admin review</span><h3 style="margin-top:16px">${name}</h3><p>No payment was taken. This protected request is waiting for an administrator to issue a quote or rejection.</p>`;
    await loadLivePremiumRequests(account); message("Premium request submitted without payment.");
  } catch (error) { message(error instanceof Error ? error.message : "Unable to submit premium request."); }
}
