async function openLiveName(name: string) { try { const contracts = new DailyContracts(); const resolved = await contracts.resolve(name); managedName = name; const primary = await contracts.reverseName(__DAILY_REVERSE_RESOLVER__, resolved.owner); const interfaces = Object.entries(resolved.interfaces).filter(([, supported]) => supported).map(([key]) => key).join(", ") || "No supported resolver interface detected"; asWindow.openModal?.(`${name} — live manager`, `<div class="row"><label>Current owner</label><input value="${resolved.owner}" readonly></div><div class="row"><label>Resolver</label><input value="${resolved.resolver ?? "Not configured"}" readonly></div><p class="muted">Supported resolver interfaces: ${interfaces}</p><div class="row"><label>Primary reverse name</label><input value="${primary || "Not selected"}" readonly></div><button class="btn ghost" onclick="dailyLiveSetPrimaryName()">Set ${name} as primary</button><div class="row"><label>ETH address record</label><input id="dailyLiveAddress" value="${resolved.addresses[60] ?? ""}" placeholder="0x..."></div><button class="btn gold" onclick="dailyLiveSaveAddress()">Save address</button><div class="row"><label>Additional coin type (SLIP-0044)</label><input id="dailyLiveCoinType" type="number" min="0" value="0"><input id="dailyLiveCoinAddress" placeholder="Address or 0x bytes"></div><button class="btn gold" onclick="dailyLiveSaveCoinAddress()">Save coin address</button><div class="row"><label>Profile text key</label><input id="dailyLiveTextKey" value="description" placeholder="description"></div><div class="row"><label>Profile text value</label><textarea id="dailyLiveTextValue" placeholder="Profile record"></textarea></div><button class="btn gold" onclick="dailyLiveSaveText()">Save profile</button><div class="row"><label>Contenthash bytes</label><input id="dailyLiveContenthash" value="${resolved.contenthash ?? ""}" placeholder="0x... (encoded contenthash bytes)"></div><button class="btn gold" onclick="dailyLiveSaveContenthash()">Save contenthash</button><div class="row"><label>Renewal years</label><input id="dailyLiveRenewYears" type="number" min="1" max="10" value="1"></div><button class="btn gold" onclick="dailyLiveRenewName()">Pay and renew</button><div class="row"><label>Transfer recipient</label><input id="dailyLiveTransferTo" placeholder="0x..."></div><button class="btn red" onclick="dailyLiveTransferName()">Transfer name</button><div class="row"><label>Subname label</label><input id="dailyLiveSubname" placeholder="team"></div><div class="row"><label>Subname owner</label><input id="dailyLiveSubnameOwner" value="${resolved.owner}" placeholder="0x..."></div><button class="btn purple" onclick="dailyLiveCreateSubname()">Create subname</button><div class="row"><label>Subname resolver</label><input id="dailyLiveSubnameResolver" value="${SEPOLIA_CONTRACTS.resolver}" placeholder="0x..."></div><button class="btn purple" onclick="dailyLiveSetSubnameResolver()">Set subname resolver</button>`, `<button class="btn ghost" onclick="closeModal()">Close</button>`); } catch (error) { message(error instanceof Error ? error.message : "Unable to resolve name."); } }
async function manageName(action: (contracts: DailyContracts, account: Awaited<ReturnType<typeof signer>>["account"]) => Promise<{ wait: () => Promise<unknown> }>, success: string) { try { if (!managedName) throw new Error("Open a Daily name before editing it."); const { provider, account } = await signer(); await (await action(new DailyContracts(provider), account)).wait(); message(success); await openLiveName(managedName); } catch (error) { message(error instanceof Error ? error.message : "Name update failed."); } }
asWindow.dailyLiveSaveAddress = () => manageName((contracts, account) => { const value = field("dailyLiveAddress"); if (!/^0x[a-fA-F0-9]{40}$/.test(value)) throw new Error("Enter a valid Ethereum address."); return contracts.setAddress(managedName, 60n, getBytes(value), account); }, "Address record confirmed on Sepolia.");
asWindow.dailyLiveSaveCoinAddress = () => manageName((contracts, account) => { const coinType = BigInt(field("dailyLiveCoinType")); const value = field("dailyLiveCoinAddress"); if (coinType < 0n || !value) throw new Error("Enter a non-negative SLIP-0044 coin type and address value."); return contracts.setAddress(managedName, coinType, /^0x[0-9a-fA-F]*$/.test(value) ? getBytes(value) : toUtf8Bytes(value), account); }, "Multichain address record confirmed on Sepolia.");
asWindow.dailyLiveSaveText = () => manageName((contracts, account) => { const key = field("dailyLiveTextKey"); const value = field("dailyLiveTextValue"); if (!key || !value) throw new Error("Enter a text-record key and value."); return contracts.setText(managedName, key, value, account); }, "Text record confirmed on Sepolia.");
