asWindow.dailyLiveCreateSubname = () => manageName((contracts, account) => { const label = field("dailyLiveSubname"); const owner = field("dailyLiveSubnameOwner"); if (!label || !/^0x[a-fA-F0-9]{40}$/.test(owner)) throw new Error("Enter a valid subname label and owner address."); return contracts.setSubname(managedName, label, owner, account); }, "Subname confirmed on Sepolia.");
