function row(result: NameSearchResult) { const selectable = result.status === "available"; const action = selectable ? `<button class="btn gold" onclick="dailyLiveRegister('${result.tld}')">Register</button>` : result.status === "premium" ? `<button class="btn ghost" onclick="openPremium('${result.name}')">Request quote</button>` : `<span class="badge ${result.status === "reserved" || result.status === "official" || result.status === "blocked" ? "red" : "gray"}">${result.status === "owned" ? "Unavailable" : result.status}</span>`; return `<div class="tld-row"><input type="checkbox" ${selectable ? "" : "disabled"} onchange="dailyLiveToggle('${result.tld}',this.checked)"><div class="tld-name">${result.name}</div><div><span class="badge ${selectable ? "green" : result.status === "premium" ? "gold" : "red"}">${result.status}</span></div><div>${selectable ? `${Number(result.priceWei ?? 0n) / 1e18} ETH` : "--"}</div><div>${action}</div></div>`; }
async function searchAll() { const input = document.getElementById("nameInput") as HTMLInputElement | null; const requested = input?.value || "oracle"; const safety = inspectLabelSafety(requested); const rows = document.getElementById("tldRows"); try { if (!safety.safe) { const alternatives = suggestLabels(requested); if (rows) rows.innerHTML = `<div class="panel section"><h3>Use a safe Daily label</h3><p>${safety.reason}</p>${alternatives.length ? `<p class="muted">Suggestions: ${alternatives.map(label => `<button class="btn ghost" style="margin:4px" onclick="document.getElementById('nameInput').value='${label}';dailyLiveSearch()">${label}</button>`).join("")}</p>` : ""}</div>`; document.getElementById("tldResults")?.classList.add("show"); return; } live.results = await new DailyContracts().search(safety.label); live.selected.clear(); if (rows) rows.innerHTML = live.results.map(row).join(""); document.getElementById("tldResults")?.classList.add("show"); renderSelection(); } catch (error) { message(error instanceof Error ? error.message : "Live name search failed."); } }
function toggle(tld: string, checked: boolean) { if (checked) live.selected.add(tld); else live.selected.delete(tld); renderSelection(); }
function storedIntent(): SavedIntent | undefined { const value = localStorage.getItem("daily-live-intent"); return value ? JSON.parse(value) as SavedIntent : undefined; }
function storedBundleIntents(): SavedIntent[] { const value = localStorage.getItem("daily-live-bundle-intents"); return value ? JSON.parse(value) as SavedIntent[] : []; }
async function commit(tld: "dly" | "day" | "daily", years = 1) { const result = live.results.find(item => item.tld === tld); if (!result) return; try { if (!Number.isInteger(years) || years < 1 || years > 10) throw new Error("Choose a registration term from 1 to 10 years."); const { provider, account } = await signer(); const contracts = new DailyContracts(provider); const owner = await account.getAddress(); let intent = contracts.createRegistration(result.name.split(".")[0], tld, owner, BigInt(years) * 365n * 24n * 60n * 60n); intent = await contracts.quoteRegistration(intent); const estimate = await contracts.estimateCommitFee(intent, account); await (await contracts.commit(intent, account)).wait(); localStorage.setItem("daily-live-intent", JSON.stringify({ ...intent, durationSeconds: intent.durationSeconds.toString(), priceWei: intent.priceWei.toString(), committedAt: Date.now() })); asWindow.openModal?.("Commitment confirmed", `<p>Your commitment for <b>${result.name}</b> is confirmed on Sepolia.</p><p>Term: <b>${years} year${years === 1 ? "" : "s"}</b>. Wait 60 seconds before revealing. Registration price: <b>${formatEther(intent.priceWei)} ETH</b>.</p><p>Estimated commitment network fee: <b>${formatEther(estimate.feeWei)} ETH</b>.</p>`, `<button class="btn ghost" onclick="closeModal()">Close</button><button class="btn gold" onclick="dailyLiveReveal()">Reveal and pay</button>`); } catch (error) { message(error instanceof Error ? error.message : "Commitment failed."); } }
async function acceptPremiumQuote(name: string, years: number) {
  try {
    const [label, suffix, extra] = name.toLowerCase().split(".");
    if (!label || !suffix || extra || !["dly", "day", "daily"].includes(suffix) || !Number.isInteger(years) || years < 1 || years > 10) throw new Error("Premium quote details are invalid.");
    const { provider, account } = await signer(); const contracts = new DailyContracts(provider);
    let intent = contracts.createRegistration(label, suffix as "dly" | "day" | "daily", await account.getAddress(), BigInt(years) * 365n * 24n * 60n * 60n);
    intent = await contracts.quoteRegistration(intent); await (await contracts.commit(intent, account)).wait();
    localStorage.setItem("daily-live-intent", JSON.stringify({ ...intent, durationSeconds: intent.durationSeconds.toString(), priceWei: intent.priceWei.toString(), committedAt: Date.now() }));
    asWindow.openModal?.("Premium commitment confirmed", `<p>Your commitment for <b>${name}</b> is confirmed on Sepolia.</p><p>The quoted registration price is <b>${formatEther(intent.priceWei)} ETH</b>. Wait 60 seconds before accepting the quote and paying.</p>`, `<button class="btn ghost" onclick="closeModal()">Close</button><button class="btn gold" onclick="dailyLiveReveal()">Accept quote and pay</button>`);
  } catch (error) { message(error instanceof Error ? error.message : "Unable to accept the premium quote."); }
}
asWindow.dailyLiveAcceptPremium = acceptPremiumQuote;
function beginRegistration(tld: "dly" | "day" | "daily") { const result = live.results.find(item => item.tld === tld); if (!result) return; asWindow.openModal?.(`Register ${result.name}`, `<div class="row"><label>Registration period</label><select id="dailyLiveRegistrationYears">${Array.from({ length: 10 }, (_, index) => `<option value="${index + 1}">${index + 1} year${index ? "s" : ""}</option>`).join("")}</select></div><p>Registration uses an on-chain commitment, then a reveal-and-payment transaction.</p>`, `<button class="btn ghost" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="dailyLiveCommitSelected('${tld}')">Commit registration</button>`); }
async function reveal() { const saved = storedIntent(); if (!saved) return message("No saved registration commitment."); if (Date.now() - saved.committedAt < 60_000) return message("Wait for the 60-second commitment age before revealing."); try { const { provider, account } = await signer(); const intent: RegistrationIntent = { ...saved, durationSeconds: BigInt(saved.durationSeconds), priceWei: BigInt(saved.priceWei) }; const estimate = await new DailyContracts(provider).estimateRegistrationFee(intent, await account.getAddress(), account); message(`Estimated reveal network fee: ${formatEther(estimate.feeWei)} ETH.`); await (await new DailyContracts(provider).register(intent, await account.getAddress(), account)).wait(); localStorage.removeItem("daily-live-intent"); asWindow.closeModal?.(); message(`${intent.label}.${intent.tld} registration confirmed.`); await searchAll(); } catch (error) { message(error instanceof Error ? error.message : "Reveal and payment failed."); } }
async function commitSelectedBundle() { try { const selected = live.results.filter(result => live.selected.has(result.tld)); if (selected.length < 2) throw new Error("Select two or three available TLDs for bundle registration."); const years = Number((document.getElementById("dailyLiveBundleYears") as HTMLSelectElement | null)?.value ?? 1); if (!Number.isInteger(years) || years < 1 || years > 10) throw new Error("Choose a registration period from 1 to 10 years."); const { provider, account } = await signer(); const contracts = new DailyContracts(provider); const owner = await account.getAddress(); const intents = await Promise.all(selected.map(async result => { const intent = contracts.createRegistration(result.name.split(".")[0], result.tld, owner, BigInt(years) * 365n * 24n * 60n * 60n); return contracts.quoteRegistration(intent); })); for (const intent of intents) await (await contracts.commit(intent, account)).wait(); localStorage.setItem("daily-live-bundle-intents", JSON.stringify(intents.map(intent => ({ ...intent, durationSeconds: intent.durationSeconds.toString(), priceWei: intent.priceWei.toString(), committedAt: Date.now() })))); asWindow.openModal?.("Bundle commitments confirmed", `<p>Commitments for <b>${selected.map(item => item.name).join(", ")}</b> are confirmed on Sepolia.</p><p>Wait 60 seconds before the single discounted bundle reveal transaction.</p>`, `<button class="btn ghost" onclick="closeModal()">Close</button><button class="btn gold" onclick="dailyLiveRevealBundle()">Reveal bundle and pay</button>`); } catch (error) { message(error instanceof Error ? error.message : "Bundle commitment failed."); } }
async function revealSelectedBundle() { try { const saved = storedBundleIntents(); if (saved.length < 2) throw new Error("No saved bundle commitments."); if (Date.now() - saved[0].committedAt < 60_000) throw new Error("Wait for the 60-second commitment age before revealing the bundle."); const { provider, account } = await signer(); const intents = saved.map(intent => ({ ...intent, durationSeconds: BigInt(intent.durationSeconds), priceWei: BigInt(intent.priceWei) })); await (await new DailyContracts(provider).registerBundle(__DAILY_BUNDLE_COORDINATOR__, intents, await account.getAddress(), account)).wait(); localStorage.removeItem("daily-live-bundle-intents"); asWindow.closeModal?.(); message("Discounted bundle registration confirmed."); await searchAll(); } catch (error) { message(error instanceof Error ? error.message : "Bundle reveal and payment failed."); } }
const walletButton = document.getElementById("walletBtn") as HTMLButtonElement | null; if (walletButton) walletButton.onclick = event => { event.preventDefault(); void connectWallet(); };
const searchButton = document.getElementById("searchNameBtn") as HTMLButtonElement | null; if (searchButton) searchButton.onclick = event => { event.preventDefault(); void searchAll(); };
const continueRegistration = document.getElementById("continueRegistration") as HTMLButtonElement | null;
if (continueRegistration) continueRegistration.onclick = event => { event.preventDefault(); const selected = live.results.filter(result => live.selected.has(result.tld)); if (selected.length === 1) { beginRegistration(selected[0].tld); return; } if (selected.length < 2) { message("Select at least one available TLD."); return; } asWindow.openModal?.("Register selected Daily bundle", `<p>You selected <b>${selected.map(item => item.name).join(", ")}</b>.</p><div class="row"><label>Registration period</label><select id="dailyLiveBundleYears">${Array.from({ length: 10 }, (_, index) => `<option value="${index + 1}">${index + 1} year${index ? "s" : ""}</option>`).join("")}</select></div><p>Each name receives its normal commitment first. After the commitment delay, the bundle coordinator submits one discounted reveal transaction.</p>`, `<button class="btn ghost" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="dailyLiveCommitBundle()">Commit selected bundle</button>`); };
asWindow.dailyLiveToggle = toggle; asWindow.dailyLiveCommit = commit; asWindow.dailyLiveReveal = reveal; (asWindow as unknown as Record<string, unknown>).dailyLiveSearch = searchAll; (asWindow as unknown as Record<string, unknown>).dailyLiveRegister = beginRegistration; (asWindow as unknown as Record<string, unknown>).dailyLiveCommitSelected = (tld: "dly" | "day" | "daily") => void commit(tld, Number((document.getElementById("dailyLiveRegistrationYears") as HTMLSelectElement | null)?.value ?? 1)); (asWindow as unknown as Record<string, unknown>).dailyLiveCommitBundle = commitSelectedBundle; (asWindow as unknown as Record<string, unknown>).dailyLiveRevealBundle = revealSelectedBundle;
void searchAll();

let mailStep = 0; let mailboxName = localStorage.getItem("daily-mailbox-name") ?? ""; let mailboxKey: MailKeyPair | undefined; let mailboxKeyHash = "";
function showLiveMail() { document.querySelectorAll(".view").forEach(view => view.classList.toggle("active", view.id === "mail")); document.querySelectorAll("#mainNav button").forEach(button => button.classList.toggle("active", (button as HTMLElement).dataset.view === "mail")); const active = Boolean(mailboxKey && mailboxName); document.getElementById("mailActivation")?.classList.toggle("active", !active); document.getElementById("mailApp")?.classList.toggle("active", active); if (active) void refreshLiveMailbox(); else renderLiveMailboxActivation(); }
async function generateLiveMailboxKey() { mailboxKey = await generateMailboxKeyPair((mailboxKey?.version ?? 0) + 1); mailboxKeyHash = await publicKeyHash(mailboxKey.publicKey); renderLiveMailboxActivation(); }
function renderLiveMailboxActivation() { const body = document.getElementById("mailActivationBody"); const pills = [...document.querySelectorAll("#mailActivationWizard .pill")]; if (!body) return; pills.forEach((pill, index) => pill.classList.toggle("active", index === mailStep)); if (mailStep === 0) body.innerHTML = `<h2>Choose an owned name</h2><p>Enter the Daily name owned by your connected Sepolia wallet.</p><div class="row"><label>Daily name</label><input id="dailyLiveMailboxName" value="${mailboxName}" placeholder="name.dly"></div>`; if (mailStep === 1) body.innerHTML = `<h2>Generate mailbox key</h2><p>The private key is generated locally and never uploaded.</p><button class="btn purple" onclick="dailyLiveGenerateMailKey()">${mailboxKey ? "Generate a replacement key" : "Generate key now"}</button>${localStorage.getItem("daily-mailbox-vault") ? `<div class="row"><label>Recovery password</label><input id="dailyLiveUnlockPassword" type="password" placeholder="Unlock local encrypted backup"></div><button class="btn ghost" onclick="dailyLiveUnlockMailKey()">Unlock saved key</button>` : ""}${mailboxKeyHash ? `<p class="badge green" style="margin-top:14px">Key version ${mailboxKey?.version} generated</p>` : ""}`; if (mailStep === 2) body.innerHTML = `<h2>Save encrypted recovery backup</h2><div class="row"><label>Backup password</label><input id="dailyLiveBackupPassword" type="password" placeholder="At least 12 characters"></div><p>Only an encrypted recovery package is saved locally. Download it and keep it somewhere you control.</p>${localStorage.getItem("daily-mailbox-vault") ? `<button class="btn ghost" onclick="dailyLiveExportMailRecovery()">Download encrypted recovery package</button>` : ""}`; if (mailStep === 3) body.innerHTML = `<h2>Publish public mail record</h2><p>Only the public-key hash and version are written to the resolver.</p><div class="row"><label>Key version</label><input value="${mailboxKey?.version ?? "--"}" readonly></div><div class="row"><label>Key hash</label><input value="${mailboxKeyHash || "Generate the key first"}" readonly></div>`; const back = document.getElementById("mailActBack") as HTMLButtonElement | null; const next = document.getElementById("mailActNext") as HTMLButtonElement | null; if (back) { back.style.visibility = mailStep === 0 ? "hidden" : "visible"; back.onclick = () => { if (mailStep > 0) { mailStep--; renderLiveMailboxActivation(); } }; } if (next) { next.textContent = mailStep === 3 ? "Activate mailbox" : "Continue"; next.onclick = () => void advanceLiveMailbox(); } }
async function advanceLiveMailbox() { try { if (mailStep === 0) { const input = document.getElementById("dailyLiveMailboxName") as HTMLInputElement | null; mailboxName = input?.value.trim() ?? ""; if (!mailboxName) throw new Error("Enter the owned Daily name for this mailbox."); localStorage.setItem("daily-mailbox-name", mailboxName); } else if (mailStep === 1 && !mailboxKey) throw new Error("Generate the local mailbox key first."); else if (mailStep === 2) { const password = (document.getElementById("dailyLiveBackupPassword") as HTMLInputElement | null)?.value ?? ""; if (!mailboxKey) throw new Error("Generate the local mailbox key first."); localStorage.setItem("daily-mailbox-vault", JSON.stringify(await encryptVault(mailboxKey, password))); } else if (mailStep === 3) { if (!mailboxKey || !mailboxKeyHash) throw new Error("Generate the mailbox key first."); const { provider, account } = await signer(); const contracts = new DailyContracts(provider); const resolved = await contracts.resolve(mailboxName); if (resolved.owner.toLowerCase() !== (await account.getAddress()).toLowerCase()) throw new Error("Only the name owner can activate this mailbox."); await (await contracts.publishMailKey(mailboxName, mailboxKeyHash, mailboxKey.version, account)).wait(); if (!apiBase) throw new Error("On-chain key published, but the Daily API URL is not configured for this build."); const registration = await fetch(`${apiBase}/v1/mailboxes`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${await apiToken(account)}` }, body: JSON.stringify({ namehash: resolved.node, publicKey: mailboxKey.publicKey, keyVersion: mailboxKey.version }) }); if (!registration.ok) throw new Error("On-chain key was published but the Daily API could not register the recipient public key."); document.getElementById("mailActivation")?.classList.remove("active"); document.getElementById("mailApp")?.classList.add("active"); message("Encrypted mailbox activated and public key record published."); return; } mailStep++; renderLiveMailboxActivation(); } catch (error) { message(error instanceof Error ? error.message : "Mailbox activation failed."); } }
asWindow.dailyLiveGenerateMailKey = generateLiveMailboxKey;
asWindow.dailyLiveUnlockMailKey = async () => { try { const raw = localStorage.getItem("daily-mailbox-vault"); const password = (document.getElementById("dailyLiveUnlockPassword") as HTMLInputElement | null)?.value ?? ""; if (!raw) throw new Error("No local encrypted recovery backup exists."); mailboxKey = await decryptVault<MailKeyPair>(JSON.parse(raw), password); mailboxKeyHash = await publicKeyHash(mailboxKey.publicKey); renderLiveMailboxActivation(); message("Local encrypted mailbox key unlocked for this browser session."); } catch { message("Unable to unlock the local encrypted mailbox backup."); } };
asWindow.dailyLiveExportMailRecovery = () => { const raw = localStorage.getItem("daily-mailbox-vault"); if (!raw) { message("Save an encrypted recovery backup before exporting it."); return; } const blob = new Blob([JSON.stringify({ format: "daily-mail-recovery-v1", mailboxName, encryptedVault: JSON.parse(raw) }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `${mailboxName || "daily-mail"}-recovery.json`; link.click(); URL.revokeObjectURL(url); message("Encrypted recovery package downloaded."); };
const mailNavigation = document.querySelector('#mainNav button[data-view="mail"]') as HTMLButtonElement | null; if (mailNavigation) mailNavigation.onclick = event => { event.preventDefault(); showLiveMail(); };

type StorageWindow = Window & { dailyLiveOpenStorage?: () => void; dailyLiveConnectStorage?: (provider: "Google Drive" | "OneDrive") => Promise<void>; dailyLiveDownloadDriveCiphertext?: () => Promise<void> };
const storageWindow = window as unknown as StorageWindow;
async function googleDriveStatus() { const { account } = await signer(); const response = await fetch(`${apiBase}/v1/storage/google-drive`, { headers: { authorization: `Bearer ${await apiToken(account)}` } }); if (!response.ok) throw new Error("Unable to load encrypted-storage status."); return response.json() as Promise<{ connected: boolean; email?: string | null }>; }
async function openLiveStorage() { try { const status = await googleDriveStatus(); asWindow.openModal?.("Encrypted mail storage", `<div class="v36-storage-grid"><div class="v36-storage-card ${status.connected ? "active" : ""}"><div style="display:flex;gap:12px;align-items:center"><div class="v36-provider-logo">G</div><div><h3 style="margin:0">Google Drive</h3><small>User-owned encrypted message folder</small></div></div><div class="v36-storage-status"><span class="badge ${status.connected ? "green" : "gray"}">${status.connected ? `Connected${status.email ? ` · ${status.email}` : ""}` : "Not connected"}</span><button class="btn purple" onclick="dailyLiveConnectStorage('Google Drive')">${status.connected ? "Reconnect" : "Connect"}</button></div></div><div class="v36-storage-card"><div style="display:flex;gap:12px;align-items:center"><div class="v36-provider-logo">O</div><div><h3 style="margin:0">OneDrive</h3><small>User-owned encrypted message folder</small></div></div><div class="v36-storage-status"><span class="badge gray">Approval required</span><button class="btn purple" onclick="dailyLiveConnectStorage('OneDrive')">Connect</button></div></div></div>${status.connected ? `<div class="row" style="margin-top:14px"><label>Google Drive ciphertext file ID</label><input id="dailyLiveDriveFileId" placeholder="Paste a Daily ciphertext file ID"></div><button class="btn ghost" onclick="dailyLiveDownloadDriveCiphertext()">Download ciphertext</button>` : ""}<div class="v36-note" style="margin-top:14px"><b>Encryption rule:</b> Messages and attachments are encrypted on the user's device before upload. The storage provider receives ciphertext only, and mailbox private keys never leave the device.</div><p class="muted">Google Drive is the Testnet connector. OneDrive remains architecture-ready and approval-gated.</p>`, `<button class="btn ghost" onclick="closeModal()">Close</button>`); } catch (error) { message(error instanceof Error ? error.message : "Unable to load encrypted storage."); } }
async function connectLiveStorage(provider: "Google Drive" | "OneDrive") { try { if (provider === "OneDrive") throw new Error("OneDrive remains approval-gated and is not operational on this Testnet release."); const { account } = await signer(); const response = await fetch(`${apiBase}/v1/storage/google-drive/connect`, { headers: { authorization: `Bearer ${await apiToken(account)}` } }); if (!response.ok) throw new Error("Unable to begin Google Drive authorization."); const { authorizationUrl } = await response.json() as { authorizationUrl: string }; window.location.assign(authorizationUrl); } catch (error) { message(error instanceof Error ? error.message : "Unable to connect encrypted storage."); } }
storageWindow.dailyLiveOpenStorage = () => { void openLiveStorage(); }; storageWindow.dailyLiveConnectStorage = connectLiveStorage;
async function uploadDriveCiphertext(filename: string, ciphertext: string, account: JsonRpcSigner) {
  const status = await googleDriveStatus(); if (!status.connected) return undefined;
  const bytes = new TextEncoder().encode(ciphertext); const base64 = btoa(Array.from(bytes, byte => String.fromCharCode(byte)).join(""));
  const response = await fetch(`${apiBase}/v1/storage/google-drive/ciphertext`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${await apiToken(account)}` }, body: JSON.stringify({ filename, ciphertextBase64: base64 }) });
  if (!response.ok) throw new Error("Google Drive rejected the ciphertext archive."); return response.json() as Promise<{ id: string }>;
}
storageWindow.dailyLiveDownloadDriveCiphertext = async () => { try { const id = (document.getElementById("dailyLiveDriveFileId") as HTMLInputElement | null)?.value.trim() ?? ""; if (!id) throw new Error("Enter a Google Drive ciphertext file ID."); const { account } = await signer(); const response = await fetch(`${apiBase}/v1/storage/google-drive/ciphertext/${encodeURIComponent(id)}`, { headers: { authorization: `Bearer ${await apiToken(account)}` } }); if (!response.ok) throw new Error("Unable to download the ciphertext file."); const href = URL.createObjectURL(await response.blob()); const link = document.createElement("a"); link.href = href; link.download = `daily-ciphertext-${id}.bin`; link.click(); URL.revokeObjectURL(href); message("Ciphertext download started; decrypt it only with the matching local mailbox key."); } catch (error) { message(error instanceof Error ? error.message : "Unable to download ciphertext."); } };
document.querySelectorAll<HTMLElement>("[onclick*='openStorageV36']").forEach(button => button.setAttribute("onclick", "dailyLiveOpenStorage()"));

let detectedMarketingLocation = false;
const marketingCategories = ["Crypto", "Developers", "Validators", "Daily app users"];
function showLiveAttention() { document.querySelectorAll(".view").forEach(view => view.classList.toggle("active", view.id === "attention")); document.querySelectorAll("#mainNav button").forEach(button => button.classList.toggle("active", (button as HTMLElement).dataset.view === "attention")); document.getElementById("attentionOptIn")?.classList.add("active"); document.getElementById("attentionDashboard")?.classList.remove("active"); renderLiveConsent(); }
function renderLiveConsent() { const body = document.getElementById("optinBody"); if (!body) return; body.innerHTML = `<h2>Voluntary Paid Attention consent</h2><p>Location is requested once in this browser. Country, state/region and city are the most precise fields used; postcode and local-area targeting are not collected.</p><div class="row"><label>Browser location</label><div><button class="btn ghost" onclick="dailyLiveDetectLocation()">Request browser location</button><p id="dailyLiveGeoStatus" class="muted">${detectedMarketingLocation ? "Browser location permission received. Confirm the country, region and city below." : "Location has not been requested."}</p></div></div><div class="row"><label>Country</label><input id="dailyLiveCountry" placeholder="Pakistan"></div><div class="row"><label>State or region</label><input id="dailyLiveRegion" placeholder="Punjab (optional)"></div><div class="row"><label>City</label><input id="dailyLiveCity" placeholder="Lahore (optional)"></div><div class="row"><label>Categories</label><div>${marketingCategories.map(category => `<label style="display:block;padding:5px 0"><input type="checkbox" class="dailyLiveCategory" value="${category}"> ${category}</label>`).join("")}</div></div><div class="row"><label>Consent</label><label><input id="dailyLiveConsentCheck" type="checkbox"> I voluntarily opt in to receive Paid Attention messages and understand that this location is locked until an approved change request.</label></div>`; const back = document.getElementById("optinBack") as HTMLButtonElement | null; const next = document.getElementById("optinNext") as HTMLButtonElement | null; if (back) back.style.visibility = "hidden"; if (next) { next.textContent = "Sign and save consent"; next.onclick = () => void saveLiveConsent(); } }
async function detectLiveMarketingLocation() { try { if (!navigator.geolocation) throw new Error("This browser does not provide geolocation."); await new Promise<GeolocationPosition>((resolve, reject) => navigator.geolocation.getCurrentPosition(resolve, reject, { enableHighAccuracy: false, timeout: 15_000, maximumAge: 0 })); detectedMarketingLocation = true; const status = document.getElementById("dailyLiveGeoStatus"); if (status) status.textContent = "Browser location permission received. Confirm the country, region and city below; no postcode is collected."; } catch (error) { message(error instanceof Error ? error.message : "Browser location permission was not granted."); } }
async function saveLiveConsent() { try { if (!apiBase) throw new Error("Daily API URL is not configured for this build."); if (!detectedMarketingLocation) throw new Error("Request browser location once before saving consent."); const country = field("dailyLiveCountry"); const region = field("dailyLiveRegion"); const city = field("dailyLiveCity"); const categories = [...document.querySelectorAll<HTMLInputElement>(".dailyLiveCategory:checked")].map(input => input.value).sort(); if (!country || !categories.length || !(document.getElementById("dailyLiveConsentCheck") as HTMLInputElement | null)?.checked) throw new Error("Confirm country, select categories, and accept the consent statement."); const { account } = await signer(); const address = await account.getAddress(); const deadline = Math.floor(Date.now() / 1000) + 15 * 60; const value = { address, country, region, city, categoriesHash: keccak256(toUtf8Bytes(JSON.stringify(categories))), deadline: BigInt(deadline) }; const signature = await account.signTypedData({ name: "Daily Marketing Consent", version: "1", chainId: DAILY_NETWORKS.sepolia.chainId, verifyingContract: SEPOLIA_CONTRACTS.registry }, { MarketingConsent: [{ name: "address", type: "address" }, { name: "country", type: "string" }, { name: "region", type: "string" }, { name: "city", type: "string" }, { name: "categoriesHash", type: "bytes32" }, { name: "deadline", type: "uint256" }] }, value); const response = await fetch(`${apiBase}/v1/marketing/consent`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${await apiToken(account)}` }, body: JSON.stringify({ address, location: { country, ...(region ? { region } : {}), ...(city ? { city } : {}) }, categories, signature, deadline }) }); if (!response.ok) throw new Error("Daily API rejected the marketing consent."); document.getElementById("attentionOptIn")?.classList.remove("active"); const dashboard = document.getElementById("attentionDashboard"); if (dashboard) { dashboard.classList.add("active"); dashboard.innerHTML = `<div class="head"><div><div class="kicker">Marketing consent saved</div><h2>Rewards and preferences</h2></div><span class="badge green">Location locked</span></div><div class="grid3"><div class="metric"><b>${country}</b><span>locked campaign country</span></div><div class="metric"><b>${categories.join(", ")}</b><span>selected categories</span></div><div class="metric"><b>0</b><span>earned rewards</span></div></div><div class="panel section"><p>Rewards and campaign messages will appear only after real funded campaign delivery.</p><button class="btn ghost" onclick="dailyLiveRequestCountryChange()">Request protected country change</button></div>`; } message("Paid Attention consent is signed and saved."); } catch (error) { message(error instanceof Error ? error.message : "Unable to save marketing consent."); } }
function requestLiveCountryChange() { asWindow.openModal?.("Request country change", `<p>Your country is locked after enrollment. A protocol administrator must approve any change.</p><div class="row"><label>Requested country</label><input id="dailyLiveRequestedCountry" placeholder="Country"></div><div class="row"><label>Reason</label><textarea id="dailyLiveCountryChangeReason" placeholder="Explain why the country should change."></textarea></div>`, `<button class="btn ghost" onclick="closeModal()">Cancel</button><button class="btn gold" onclick="dailyLiveSubmitCountryChange()">Submit for review</button>`); }
async function openPaidAttentionInbox() { try { const { account } = await signer(); const response = await fetch(`${apiBase}/v1/marketing/inbox`, { headers: { authorization: `Bearer ${await apiToken(account)}` } }); if (!response.ok) throw new Error("Unable to load Paid Attention inbox."); const { messages } = await response.json() as { messages: Array<{ id: string; creative: { text: string; imageUrl?: string; clickableUrl: string }; status: string; delivered_at: string }> }; asWindow.openModal?.("Paid Attention inbox", messages.length ? messages.map(item => `<div class="panel section"><span class="badge ${item.status === "read" ? "gray" : "gold"}">${item.status}</span><p style="white-space:pre-wrap">${item.creative.text.replace(/[&<>]/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[character]!)}</p>${item.creative.imageUrl ? `<img src="${item.creative.imageUrl}" alt="Campaign creative" style="max-width:100%;border-radius:12px">` : ""}<p><a href="${item.creative.clickableUrl}" target="_blank" rel="noreferrer">Open advertiser link</a></p><button class="btn ghost" onclick="dailyLivePaidInboxAction('${item.id}','read')">Mark read</button> <button class="btn red" onclick="dailyLivePaidInboxAction('${item.id}','dismiss')">Dismiss</button></div>`).join("") : "<p>No Paid Attention messages are available.</p>", `<button class="btn ghost" onclick="closeModal()">Close</button>`); } catch (error) { message(error instanceof Error ? error.message : "Unable to load Paid Attention inbox."); } }
async function submitLiveCountryChange() { try { if (!apiBase) throw new Error("Daily API URL is not configured for this build."); const requestedCountry = field("dailyLiveRequestedCountry"); const reason = field("dailyLiveCountryChangeReason"); if (!requestedCountry || reason.length < 10) throw new Error("Enter the requested country and a reason of at least 10 characters."); const { account } = await signer(); const response = await fetch(`${apiBase}/v1/marketing/country-changes`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${await apiToken(account)}` }, body: JSON.stringify({ requestedCountry, reason }) }); if (!response.ok) throw new Error((await response.json().catch(() => ({ error: "Country-change request failed." })) as { error?: string }).error ?? "Country-change request failed."); asWindow.closeModal?.(); message("Country-change request submitted for protected admin review."); } catch (error) { message(error instanceof Error ? error.message : "Unable to request country change."); } }
