async function hashText(value: string) { return `0x${Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)))).map(byte => byte.toString(16).padStart(2, "0")).join("")}`; }
function openLiveCompose() {
  asWindow.openModal?.("Compose encrypted message", `<div class="row"><label>Recipient Daily name</label><input id="dailyLiveMailRecipient" placeholder="recipient.dly"></div><div class="row"><label>Message</label><textarea id="dailyLiveMailBody" placeholder="Write an encrypted message"></textarea></div><div class="row"><label>Attachments</label><input id="dailyLiveMailAttachments" type="file" multiple><small>Up to five files and 8 MiB total before encryption. Files are included only inside the encrypted payload.</small></div><p>Recipient public-key metadata is verified against the current on-chain mailbox key before encryption.</p>`, `<button class="btn ghost" onclick="closeModal()">Cancel</button><button class="btn purple" onclick="dailyLiveSendMail()">Encrypt and send</button>`);
}
async function encryptedAttachments(files: FileList | null) {
  const selected = [...(files ?? [])]; if (selected.length > 5) throw new Error("Attach no more than five files.");
  if (selected.reduce((total, file) => total + file.size, 0) > 8 * 1024 * 1024) throw new Error("Encrypted attachments are limited to 8 MiB in total.");
  return Promise.all(selected.map(async file => ({ name: file.name, type: file.type || "application/octet-stream", bytes: file.size, data: btoa(Array.from(new Uint8Array(await file.arrayBuffer()), byte => String.fromCharCode(byte)).join("")) })));
}
async function sendLiveMail() {
  try {
    if (!apiBase) throw new Error("Daily API URL is not configured for this build.");
    const recipient = (document.getElementById("dailyLiveMailRecipient") as HTMLInputElement | null)?.value.trim() ?? "";
    const plaintext = (document.getElementById("dailyLiveMailBody") as HTMLTextAreaElement | null)?.value ?? ""; const attachments = await encryptedAttachments((document.getElementById("dailyLiveMailAttachments") as HTMLInputElement | null)?.files ?? null);
    if (!recipient || !plaintext.trim()) throw new Error("Enter both a recipient Daily name and a message.");
    const { provider, account } = await signer(); const contracts = new DailyContracts(provider); const resolved = await contracts.resolve(recipient);
    const keyResponse = await fetch(`${apiBase}/v1/mailboxes/${resolved.node}`); if (!keyResponse.ok) throw new Error("Recipient has not published a current encrypted mailbox key.");
    const key = await keyResponse.json() as { publicKey: JsonWebKey; keyVersion: number };
    const ciphertext = JSON.stringify(await encryptForRecipient(key.publicKey, JSON.stringify({ body: plaintext, attachments, sentAt: new Date().toISOString() }), key.keyVersion)); const nonce = BigInt(Date.now()).toString(); const deadline = Math.floor(Date.now() / 1000) + 86_400; const from = await account.getAddress();
    const value = { from, toNamehash: resolved.node, ciphertextHash: await hashText(ciphertext), nonce: BigInt(nonce), deadline: BigInt(deadline) };
    const signature = await account.signTypedData({ name: "Daily Mail", version: "1", chainId: DAILY_NETWORKS.sepolia.chainId, verifyingContract: SEPOLIA_CONTRACTS.registry }, MAIL_ENVELOPE_TYPES, value);
    const response = await fetch(`${apiBase}/v1/mail/envelopes`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${await apiToken(account)}` }, body: JSON.stringify({ from, recipientNamehash: resolved.node, ciphertext, signature, nonce, deadline }) });
    if (!response.ok) throw new Error("Daily Mail relay rejected the encrypted envelope.");
    let archive = "";
    try { const stored = await uploadDriveCiphertext(`daily-mail-${Date.now()}.ciphertext`, ciphertext, account); if (stored) archive = ` Ciphertext archive: ${stored.id}.`; } catch (storageError) { message(storageError instanceof Error ? `${storageError.message} Mail delivery still succeeded.` : "Mail delivery succeeded, but the optional ciphertext archive failed."); }
    asWindow.closeModal?.(); message(`Encrypted envelope accepted by the Daily Mail relay.${archive}`);
  } catch (error) { message(error instanceof Error ? error.message : "Encrypted mail could not be sent."); }
}
type LiveMessage = { id: string; senderAddress: string; ciphertext: string; createdAt: string; state: string };
let receivedMessages: Array<LiveMessage & { plaintext: string }> = [];
async function refreshLiveMailbox() {
  try {
    if (!mailboxKey || !mailboxName || !apiBase) return;
    const { provider, account } = await signer(); const node = (await new DailyContracts(provider).resolve(mailboxName)).node;
    const response = await fetch(`${apiBase}/v1/mail/${node}`, { headers: { authorization: `Bearer ${await apiToken(account)}` } });
    if (!response.ok) throw new Error("Daily Mail relay could not load the mailbox.");
    const payload = await response.json() as { messages: LiveMessage[] };
    receivedMessages = await Promise.all(payload.messages.map(async item => { try { return { ...item, plaintext: await decryptForRecipient(mailboxKey!.privateKey, JSON.parse(item.ciphertext)) }; } catch { return { ...item, plaintext: "Unable to decrypt this envelope with the active local mailbox key." }; } }));
    const list = document.getElementById("mailList"); const reader = document.getElementById("mailReader");
    if (list) list.innerHTML = `<div class="head"><div><h2>Inbox</h2><p>Encrypted Daily Mail</p></div><button class="btn purple" onclick="openCompose()">Compose message</button></div>${receivedMessages.length ? receivedMessages.map((item, index) => `<div class="msg ${index === 0 ? "active" : ""}" onclick="dailyLiveReadMail(${index})"><b>${item.senderAddress}</b><span>${item.state}</span><small>${new Date(item.createdAt).toLocaleString()}</small></div>`).join("") : `<div class="panel section"><p>No encrypted messages have been received.</p><button class="btn purple" onclick="openCompose()">Compose message</button></div>`}`;
    if (!receivedMessages.length && reader) reader.innerHTML = `<div class="panel section"><h3>No message selected</h3><p>New ciphertext-only envelopes will appear here.</p></div>`;
    if (receivedMessages.length) await readLiveMessage(0);
  } catch (error) { message(error instanceof Error ? error.message : "Unable to load encrypted mailbox."); }
}
async function openLiveArchivedMail() { try { if (!mailboxKey || !mailboxName || !apiBase) throw new Error("Activate an encrypted mailbox first."); const { provider, account } = await signer(); const node = (await new DailyContracts(provider).resolve(mailboxName)).node; const response = await fetch(`${apiBase}/v1/mail/${node}?folder=archived`, { headers: { authorization: `Bearer ${await apiToken(account)}` } }); if (!response.ok) throw new Error("Daily Mail could not load archived envelopes."); const { messages } = await response.json() as { messages: LiveMessage[] }; receivedMessages = await Promise.all(messages.map(async item => { try { return { ...item, plaintext: await decryptForRecipient(mailboxKey!.privateKey, JSON.parse(item.ciphertext)) }; } catch { return { ...item, plaintext: "Unable to decrypt this envelope with the active local mailbox key." }; } })); const list = document.getElementById("mailList"); const reader = document.getElementById("mailReader"); if (list) list.innerHTML = `<div class="head"><div><h2>Archived</h2><p>Encrypted Daily Mail</p></div><button class="btn purple" onclick="openCompose()">Compose message</button></div>${receivedMessages.length ? receivedMessages.map((item, index) => `<div class="msg" onclick="dailyLiveReadMail(${index})"><b>${item.senderAddress}</b><span>${item.state}</span><small>${new Date(item.createdAt).toLocaleString()}</small></div>`).join("") : '<div class="panel section"><p>No archived encrypted messages.</p></div>'}`; if (reader) reader.innerHTML = '<div class="panel section"><h3>Archived messages</h3><p>Select an envelope to decrypt it locally.</p></div>'; } catch (error) { message(error instanceof Error ? error.message : "Unable to load archived mail."); } }
async function openLiveSentMail() { try { const { account } = await signer(); const address = await account.getAddress(); const response = await fetch(`${apiBase}/v1/mail/sent/${address}`, { headers: { authorization: `Bearer ${await apiToken(account)}` } }); if (!response.ok) throw new Error("Daily Mail could not load sent envelopes."); const { messages } = await response.json() as { messages: Array<{ id: string; recipientNamehash: string; createdAt: string; state: string }> }; const list = document.getElementById("mailList"); const reader = document.getElementById("mailReader"); if (list) list.innerHTML = `<div class="head"><div><h2>Sent</h2><p>Encrypted delivery receipts</p></div><button class="btn purple" onclick="openCompose()">Compose message</button></div>${messages.length ? messages.map(item => `<div class="msg"><b>${item.recipientNamehash}</b><span>${item.state}</span><small>${new Date(item.createdAt).toLocaleString()}</small></div>`).join("") : '<div class="panel section"><p>No encrypted messages have been sent.</p></div>'}`; if (reader) reader.innerHTML = '<div class="panel section"><h3>Sent ciphertext</h3><p>Only envelope status is available to the sender; recipient plaintext remains encrypted to the recipient key.</p></div>'; } catch (error) { message(error instanceof Error ? error.message : "Unable to load sent mail."); } }
